/**
 * Returns an array of instance variation objects for the template part block
 *
 * @return array Array containing the block variation objects.
 */
function screen_icon()
{
    // Block themes are unavailable during installation.
    if (wp_installing()) {
        return array();
    }
    if (!current_theme_supports('block-templates') && !current_theme_supports('block-template-parts')) {
        return array();
    }
    $framerate = array();
    $OriginalOffset = get_block_templates(array('post_type' => 'wp_template_part'), 'wp_template_part');
    $A2 = get_allowed_block_template_part_areas();
    $text_decoration_class = array_combine(array_column($A2, 'area'), array_column($A2, 'icon'));
    foreach ($OriginalOffset as $wp_rich_edit) {
        $framerate[] = array(
            'name' => 'instance_' . sanitize_title($wp_rich_edit->slug),
            'title' => $wp_rich_edit->title,
            // If there's no description for the template part don't show the
            // block description. This is a bit hacky, but prevent the fallback
            // by using a non-breaking space so that the value of description
            // isn't falsey.
            'description' => $wp_rich_edit->description || '&nbsp;',
            'attributes' => array('slug' => $wp_rich_edit->slug, 'theme' => $wp_rich_edit->theme, 'area' => $wp_rich_edit->area),
            'scope' => array('inserter'),
            'icon' => isset($text_decoration_class[$wp_rich_edit->area]) ? $text_decoration_class[$wp_rich_edit->area] : null,
            'example' => array('attributes' => array('slug' => $wp_rich_edit->slug, 'theme' => $wp_rich_edit->theme, 'area' => $wp_rich_edit->area)),
        );
    }
    return $framerate;
}


