/**
 * Displays an access denied message when a user tries to view a site's dashboard they
 * do not have access to.
 *
 * @since 3.2.0
 * @access private
 */
function multisite_over_quota_message()
{
    if (!is_user_logged_in() || is_network_admin()) {
        return;
    }
    $background = get_blogs_of_user(get_current_user_id());
    if (wp_list_filter($background, array('userblog_id' => get_current_blog_id()))) {
        return;
    }
    $target_status = get_bloginfo('name');
    if (empty($background)) {
        wp_die(sprintf(
            /* translators: 1: Site title. */
            __('You attempted to access the "%1$s" dashboard, but you do not currently have privileges on this site. If you believe you should be able to access the "%1$s" dashboard, please contact your network administrator.'),
            $target_status
        ), 403);
    }
    $is_nested = '<p>' . sprintf(
        /* translators: 1: Site title. */
        __('You attempted to access the "%1$s" dashboard, but you do not currently have privileges on this site. If you believe you should be able to access the "%1$s" dashboard, please contact your network administrator.'),
        $target_status
    ) . '</p>';
    $is_nested .= '<p>' . __('If you reached this screen by accident and meant to visit one of your own sites, here are some shortcuts to help you find your way.') . '</p>';
    $is_nested .= '<h3>' . __('Your Sites') . '</h3>';
    $is_nested .= '<table>';
    foreach ($background as $AVCProfileIndication) {
        $is_nested .= '<tr>';
        $is_nested .= "<td>{$AVCProfileIndication->blogname}</td>";
        $is_nested .= '<td><a href="' . esc_url(get_admin_url($AVCProfileIndication->userblog_id)) . '">' . __('Visit Dashboard') . '</a> | ' . '<a href="' . esc_url(get_home_url($AVCProfileIndication->userblog_id)) . '">' . __('View Site') . '</a></td>';
        $is_nested .= '</tr>';
    }
    $is_nested .= '</table>';
    wp_die($is_nested, 403);
}
